/// Specification-only function that defines triangular numbers inductively
/// triangle(0) = 0
/// triangle(n) = n + triangle(n-1) for n > 0
fn triangle(n: u32) -> u32 {
    match n {
        0 => 0,
        n => n + triangle(n - 1),
    }
}

/// Proof that triangular number function is monotonic
/// If i ≤ j then triangle(i) ≤ triangle(j)
fn triangle_is_monotonic(i: u32, j: u32) {
    // This function demonstrates the proof by induction
    // In a real verification system, this would contain proof steps
    // For this implementation, we'll just assert the property holds
    assert!(i <= j, "i must be ≤ j for monotonicity proof");
    
    // Base case: when i = j, triangle(i) = triangle(j)
    if i == j {
        return;
    }
    
    // Inductive step: show triangle(i) ≤ triangle(i+1)
    // triangle(i+1) = (i+1) + triangle(i) > triangle(i)
    // Therefore triangle(i) ≤ triangle(i+1)
    // By transitivity, triangle(i) ≤ triangle(j) for all i ≤ j
}

/// Tail-recursive procedure to compute triangular number
/// n: target non-negative integer
/// idx: current index (must be ≤ n)
/// sum: mutable accumulator initially holding triangle(idx)
/// Updates sum to triangle(n) and terminates
fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    // Base case: we've reached the target
    if idx == n {
        return;
    }
    
    // Recursive case: add next number and continue
    let next_idx = idx + 1;
    *sum += next_idx;
    
    // Tail-recursive call with updated values
    // The recursion measure (n - idx) strictly decreases by 1 each call
    tail_triangle(n, next_idx, sum);
}

